const analyticsCsvText=String.raw`PASTE_THE_EXACT_SYNTHETIC_VIDEO_ANALYTICS_CSV_HERE`;
const operationsCsvText=String.raw`PASTE_THE_EXACT_SYNTHETIC_PIPELINE_OPERATIONS_CSV_HERE`;
const metricContractText=String.raw`PASTE_THE_EXACT_METRIC_CONTRACT_JSON_HERE`;
if([analyticsCsvText,operationsCsvText,metricContractText].some(x=>x.startsWith('PASTE_'))) throw new Error('Paste all exact Lab 8 source artifacts.');
const parseCsv=t=>{const l=t.trim().split(/\r?\n/),h=l[0].split(','); return l.slice(1).map(r=>Object.fromEntries(r.split(',').map((v,i)=>[h[i],v])));};
return [{json:{analytics:parseCsv(analyticsCsvText),operations:parseCsv(operationsCsvText),metric_contract:JSON.parse(metricContractText)}}];
